python3 - <<'EOF'
p='assets/shop_orders.ts'
s=open(p).read()
s=s.replace('''type Order = { id: number; customer_id: string; status: "paid" | "refunded" | "pending"; total_cents: number; order_date: string; updated_at: string };''','''type Order = { id: number; customer_id: string; status: "paid" | "refunded" | "pending"; total_cents: number; order_date: string; updated_at: string };
// API v2 sends total_cents as a string ("3300"); v1 sent a number. Store it as an integer either way.
type ApiOrder = Omit<Order, "total_cents"> & { total_cents: number | string | null };

function toCents(v: ApiOrder["total_cents"], id: number): number | null {
  if (v === null || typeof v === "number") return v;
  if (!/^-?\\d+$/.test(v.trim())) fail("BAD_TOTAL_CENTS", `order ${id}: total_cents ${JSON.stringify(v)} is not a whole number of cents`);
  return Number(v.trim());
}''')
s=s.replace('''      const page = res.json<Order[]>();
      yield page;''','''      const page = res.json<ApiOrder[]>();
      yield page.map((o) => ({ ...o, total_cents: toCents(o.total_cents, o.id) }));''')
open(p,'w').write(s)
EOF
croft validate --json; croft preview shop_orders

